# --- TYPE-FREE: `[]=` and the attribute writer, on every receiver shape ------
#
# `[]=` is a member of all three vendored sets AND of upstream's
# `UNIVERSAL_MUTATORS`, so it is claimed on every receiver with no class
# needed; `slot=` is its twin through `ATTRIBUTE_WRITER`. Eight spellings
# each: the two plain calls plus the six compound-write node types the
# collector branches on individually, which bypass the catalogue entirely
# and so are pure ownership readings on both sides.
#
# This is the section where the port PROVES `mutate.*` today, so it is the
# one an ownership divergence would surface in — as an OVER, not as silence.

class TypeFree
  # a frame-owned local: mutate.local — the plain `[]=` call
  def owned_index_set
    recv = []
    recv[0] = 1
    nil
  end

  # a frame-owned local: mutate.local — IndexOperatorWriteNode
  def owned_index_op
    recv = []
    recv[0] += 1
    nil
  end

  # a frame-owned local: mutate.local — IndexOrWriteNode
  def owned_index_or
    recv = []
    recv[0] ||= 1
    nil
  end

  # a frame-owned local: mutate.local — IndexAndWriteNode
  def owned_index_and
    recv = []
    recv[0] &&= 1
    nil
  end

  # a frame-owned local: mutate.local — the plain attribute-writer call
  def owned_writer
    recv = []
    recv.slot = 1
    nil
  end

  # a frame-owned local: mutate.local — CallOperatorWriteNode
  def owned_writer_op
    recv = []
    recv.slot += 1
    nil
  end

  # a frame-owned local: mutate.local — CallOrWriteNode
