# --- TYPE-FREE, in a SINGLETON unit ------------------------------------------
#
# `class << self` flips the axis that separates `mutate.self` from
# `mutate.static` for self and its ivars, and leaves a local alone
# (`mutation_classifier.rb:80`). Same eight spellings.

class TypeFreeSingleton
  class << self
    # a frame-owned local: mutate.local — the plain `[]=` call
    def owned_index_set
      recv = []
      recv[0] = 1
      nil
    end

    # a frame-owned local: mutate.local — IndexOperatorWriteNode
    def owned_index_op
      recv = []
      recv[0] += 1
      nil
    end

    # a frame-owned local: mutate.local — IndexOrWriteNode
    def owned_index_or
      recv = []
      recv[0] ||= 1
      nil
    end

    # a frame-owned local: mutate.local — IndexAndWriteNode
    def owned_index_and
      recv = []
      recv[0] &&= 1
      nil
    end

    # a frame-owned local: mutate.local — the plain attribute-writer call
    def owned_writer
      recv = []
      recv.slot = 1
      nil
    end

    # a frame-owned local: mutate.local — CallOperatorWriteNode
    def owned_writer_op
      recv = []
      recv.slot += 1
      nil
    end

    # a frame-owned local: mutate.local — CallOrWriteNode
    def owned_writer_or
      recv = []
      recv.slot ||= 1
      nil
    end

    # a frame-owned local: mutate.local — CallAndWriteNode
    def owned_writer_and
      recv = []
      recv.slot &&= 1
      nil
    end

    # an ivar read: mutate.self — the plain `[]=` call
    def ivar_index_set
      @recv = []
      @recv[0] = 1
      nil
    end

    # an ivar read: mutate.self — IndexOperatorWriteNode
    def ivar_index_op
      @recv = []
      @recv[0] += 1
      nil
    end

    # an ivar read: mutate.self — IndexOrWriteNode
    def ivar_index_or
      @recv = []
      @recv[0] ||= 1
      nil
    end

    # an ivar read: mutate.self — IndexAndWriteNode
    def ivar_index_and
      @recv = []
      @recv[0] &&= 1
      nil
    end

    # an ivar read: mutate.self — the plain attribute-writer call
    def ivar_writer
      @recv = []
      @recv.slot = 1
      nil
    end

    # an ivar read: mutate.self — CallOperatorWriteNode
    def ivar_writer_op
      @recv = []
      @recv.slot += 1
      nil
    end

    # an ivar read: mutate.self — CallOrWriteNode
    def ivar_writer_or
      @recv = []
      @recv.slot ||= 1
      nil
    end

    # an ivar read: mutate.self — CallAndWriteNode
    def ivar_writer_and
      @recv = []
      @recv.slot &&= 1
      nil
    end

    # self: mutate.self — the plain `[]=` call
    def selfrecv_index_set
      self[0] = 1
      nil
    end

    # self: mutate.self — IndexOperatorWriteNode
    def selfrecv_index_op
      self[0] += 1
      nil
    end

    # self: mutate.self — IndexOrWriteNode
    def selfrecv_index_or
      self[0] ||= 1
      nil
    end

    # self: mutate.self — IndexAndWriteNode
    def selfrecv_index_and
      self[0] &&= 1
      nil
    end

    # self: mutate.self — the plain attribute-writer call
    def selfrecv_writer
      self.slot = 1
      nil
    end

    # self: mutate.self — CallOperatorWriteNode
    def selfrecv_writer_op
      self.slot += 1
      nil
    end

    # self: mutate.self — CallOrWriteNode
    def selfrecv_writer_or
      self.slot ||= 1
      nil
    end

    # self: mutate.self — CallAndWriteNode
    def selfrecv_writer_and
      self.slot &&= 1
      nil
    end
  end
end

# --- control: a ROWED mutator selector is the ROW's answer, not a mutation ---
#
# Every catalogued row (10) whose selector is in a vendored set and whose
# owner a CONSTANT receiver can spell. `Catalog#lookup` reads the row first
# and a row is not a receiver mutation unless it says so, so `ENV.clear` is
# `global.write` and nothing else — never `mutate.*`. These must stay MATCH:
# a port that let a set membership override a row would show up here as an
# OVER, and one that stopped reading rows would lose every label below.

class Rowed
  # File.delete: io.fs.write
  def r_file_delete
    File.delete
  end

  # Dir.delete: io.fs.write
  def r_dir_delete
    Dir.delete
  end

  # ENV#[]=: global.write
  def r_env_index_set
    ENV[0] = 1
  end

  # ENV#store: global.write
  def r_env_store
    ENV.store
  end

  # ENV#delete: global.write
  def r_env_delete
    ENV.delete
  end

  # ENV#update: global.write
  def r_env_update
    ENV.update
  end

  # ENV#merge!: global.write
  def r_env_merge_bang
    ENV.merge!
  end

  # ENV#replace: global.write
  def r_env_replace
    ENV.replace
  end

  # ENV#clear: global.write
  def r_env_clear
    ENV.clear
  end

  # Warning.[]=: global.write
  def r_warning_index_set
    Warning[0] = 1
  end
end

# --- control: the selectors a row answers as a NON-mutation stay SUPPRESSED ---
#
# The 5 rows behind `NON_MUTATING_ROWED_SELECTORS` (`collect.rs`): a
# universally-mutating selector that some catalogue row answers as a plain
# effect. Upstream reaches those rows through the TYPER, for a receiver this
# port cannot name from syntax — so the port suppresses the label rather
# than mirroring a typing it does not have.
#
# The receiver is made provably-owned wherever the class has an allocator,
# which is what makes the suppression falsifiable: the oracle proves the
# ROW's label, and a port that dropped the suppression would prove
# `mutate.local` beside it — a label the oracle does not prove, i.e. an OVER.

class Suppressed
  # ENV#[]= -> global.write (an object constant has no allocator)
  def s_env_index_set
    recv = ENV
    recv[0] = 1
    nil
  end

  # Thread#[]= -> global.write (a provably-owned instance — the FATAL member)
  def s_thread_index_set
    recv = Thread.new
    recv[0] = 1
    nil
  end

  # Warning#[]= -> global.write (a singleton row: the receiver is the class object)
  def s_warning_index_set
    recv = Warning
    recv[0] = 1
    nil
  end

  # Encoding#default_external= -> global.write (a singleton row: the receiver is the class object)
  def s_encoding_default_external_set
    recv = Encoding
    recv.default_external = 1
    nil
  end

  # Encoding#default_internal= -> global.write (a singleton row: the receiver is the class object)
  def s_encoding_default_internal_set
    recv = Encoding
    recv.default_internal = 1
    nil
  end
end
